import{_ as a,o as n,c as t,a3 as l}from"./chunks/framework.MGD2uYU7.js";const g=JSON.parse('{"title":"SC-44 — Danh sách phiên đấu giá (admin)","description":"","frontmatter":{"title":"SC-44 — Danh sách phiên đấu giá (admin)"},"headers":[],"relativePath":"wireframes/admin/sc-44-danh-sach-phien.md","filePath":"wireframes/admin/sc-44-danh-sach-phien.md","lastUpdated":null}'),i={name:"wireframes/admin/sc-44-danh-sach-phien.md"};function c(p,s,e,d,o,h){return n(),t("div",null,[...s[0]||(s[0]=[l('<h1 id="sc-44-—-danh-sach-phien-đau-gia-admin" tabindex="-1">SC-44 — Danh sách phiên đấu giá (admin) <a class="header-anchor" href="#sc-44-—-danh-sach-phien-đau-gia-admin" aria-label="Permalink to &quot;SC-44 — Danh sách phiên đấu giá (admin)&quot;">​</a></h1><p><span class="wf-badge danger">ADMIN</span> <span class="wf-badge info">Route: /admin/dau-gia</span> <span class="wf-badge muted">Nguồn: docs/05 §3 (SC-40..49) · docs/06 endpoints 54–58 · docs/08 BR-AU · docs/03 UC-11</span></p><p><strong>Ai xem màn này</strong>: ADMIN vận hành đấu giá (Ops An Phuc). Đây là &quot;trung tâm điều khiển&quot; mảng đấu giá: xem toàn bộ phiên theo trạng thái, tạo phiên mới (SC-45), công bố, hủy, và nhảy vào monitor phiên LIVE (SC-46). <strong>Mục đích</strong>: DataTable server-side + tabs theo state machine <code>auctions.state</code>; hành động nguy hiểm (cancel) luôn đi qua modal xác nhận có <strong>lý do bắt buộc</strong>; mọi mutation → <strong>toast + audit log</strong>. <strong>Ví dụ số dùng trong bản vẽ</strong>: phiên LIVE <code>DGA-2026-0001</code> (auc_01J9X3K8M2) — căn <code>CT2-A18.05</code> dự án NOXH <code>HP-380</code>, giá khởi điểm <code>1.800.000.000 ₫</code>, bước giá <code>18.000.000 ₫</code> (1%), 7 người tham gia ACTIVE.</p><h2 id="_1-desktop-—-tabs-trang-thai-bang-phien-server-side-datatable" tabindex="-1">1. Desktop — tabs trạng thái + bảng phiên (server-side DataTable) <a class="header-anchor" href="#_1-desktop-—-tabs-trang-thai-bang-phien-server-side-datatable" aria-label="Permalink to &quot;1. Desktop — tabs trạng thái + bảng phiên (server-side DataTable)&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/admin/dau-gia?state=all&amp;page=1</span></div><div class="wf-body"><div class="wf-row" style="align-items:stretch;gap:0;"><div class="wf-admin-rail"><span class="brand">AnPhuc Admin</span><span class="item">Dashboard</span><span class="item">KYC</span><span class="item">Tin</span><span class="item">Dự án</span><span class="item active">Đấu giá</span><span class="item">Thanh toán</span><span class="item">Người dùng</span><span class="item">Audit</span></div><div class="wf-grow wf-col" style="padding:16px;min-width:0;gap:12px;"><div class="wf-row between middle"><span class="wf-title lg">Phiên đấu giá <span class="wf-callout">1</span></span><span class="wf-row middle" style="gap:8px;"><span class="wf-btn sm ghost">Xuất CSV <span class="wf-callout">9</span></span><span class="wf-btn primary">+ Tạo phiên <span class="wf-callout" style="background:#fff;color:var(--wf-accent);">5</span></span></span></div><div class="wf-tabs"><span class="wf-tab active">Tất cả (12)</span><span class="wf-tab">DRAFT (2)</span><span class="wf-tab">PUBLISHED (1)</span><span class="wf-tab">IN_PROGRESS (1)</span><span class="wf-tab">AWARDED (6)</span><span class="wf-tab">FAILED (1)</span><span class="wf-tab">CANCELLED (1)</span></div><table class="wf-table"><thead><tr><th>Phiên</th><th>Căn / Dự án</th><th>Khởi điểm</th><th>Bắt đầu ▲</th><th>Trạng thái</th><th>Tham gia</th><th>Hành động</th></tr></thead><tbody><tr><td><b>DGA-2026-0001</b><br><span class="wf-small">auc_01J9X3K8M2</span></td><td>CT2-A18.05<br><span class="wf-small">NOXH HP-380 · 72 m² · 2 PN</span></td><td><span class="wf-money">1.800.000.000 ₫</span><br><span class="wf-small">bước 18.000.000 (1%)</span></td><td>09/10/2026 14:00<br><span class="wf-small">GMT+7</span></td><td><span class="wf-badge danger live">IN_PROGRESS</span></td><td>7 ACTIVE<br><span class="wf-small">19 lượt giá</span></td><td><span class="wf-btn sm primary">Monitor → SC-46</span></td></tr><tr><td><b>DGA-2026-0003</b><br><span class="wf-small">auc_01J9Y4B7C1</span></td><td>CT1-B07.03<br><span class="wf-small">NOXH HP-380 · 69,5 m²</span></td><td><span class="wf-money">1.450.000.000 ₫</span><br><span class="wf-small">bước 14.500.000 (1%)</span></td><td>12/10/2026 09:00<br><span class="wf-small">đóng ĐK 11/10 09:00</span></td><td><span class="wf-badge info">PUBLISHED</span></td><td>3 ACTIVE<br><span class="wf-small">2 PENDING_DEPOSIT</span></td><td><span class="wf-btn sm">Xem</span> <span class="wf-btn sm danger">Hủy <span class="wf-callout" style="background:#fff;color:var(--wf-danger);">6</span></span></td></tr><tr><td><b>DGA-2026-0004</b><br><span class="wf-small">auc_01J9Y6D3F8</span></td><td>TB2-03.11<br><span class="wf-small">NOXH BN-210 · 55 m²</span></td><td><span class="wf-money">980.000.000 ₫</span><br><span class="wf-small">bước 9.800.000 (1%)</span></td><td>20/10/2026 09:00<br><span class="wf-small">GMT+7</span></td><td><span class="wf-badge muted">DRAFT</span></td><td>—</td><td><span class="wf-btn sm">Sửa → SC-45</span> <span class="wf-btn sm ok">Công bố <span class="wf-callout">7</span></span> <span class="wf-btn sm danger">Hủy</span></td></tr><tr><td><b>DGA-2025-0118</b><br><span class="wf-small">auc_01J9K2M5P9</span></td><td>CT1-A08.03<br><span class="wf-small">NOXH HP-380 · 70 m²</span></td><td><span class="wf-money">1.250.000.000 ₫</span><br><span class="wf-small">chốt 1.310.000.000</span></td><td>05/10/2026 09:00<br><span class="wf-small">kết thúc 05/10 15:02</span></td><td><span class="wf-badge ok">AWARDED</span></td><td>23 ACTIVE<br><span class="wf-small">31 lượt giá</span></td><td><span class="wf-btn sm">Xem (read-only)</span></td></tr><tr><td><b>DGA-2025-0117</b><br><span class="wf-small">auc_01J9J8R2T4</span></td><td>HH1-05.02<br><span class="wf-small">NOXH HN-118 · 60 m²</span></td><td><span class="wf-money">1.100.000.000 ₫</span></td><td>02/10/2026 09:00<br><span class="wf-small">kết thúc 02/10 09:45</span></td><td><span class="wf-badge warn">FAILED — 0 giá</span></td><td>2 ACTIVE<br><span class="wf-small">tin về LISTED</span></td><td><span class="wf-btn sm">Xem (read-only)</span></td></tr><tr><td><b>DGA-2025-0115</b><br><span class="wf-small">auc_01J9H4W6X1</span></td><td>CT3-C12.08<br><span class="wf-small">NOXH HP-380 · 72 m²</span></td><td><span class="wf-money">1.600.000.000 ₫</span></td><td>—<br><span class="wf-small">hủy 28/09/2026 10:12</span></td><td><span class="wf-badge muted">CANCELLED</span><br><span class="wf-small">&quot;Chủ nhà khiếu nại sổ — chờ pháp chế&quot;</span></td><td>1 ACTIVE<br><span class="wf-small">đã refund 100%</span></td><td><span class="wf-btn sm">Xem (read-only)</span></td></tr></tbody></table><div class="wf-row between middle"><span class="wf-small">Trang 1/2 · 12 phiên · sort mặc định: bắt đầu giảm dần <span class="wf-callout">2</span></span><div class="wf-pagination" style="margin-top:0;"><span class="pg">‹</span><span class="pg active">1</span><span class="pg">2</span><span class="pg">›</span></div></div></div></div><div class="wf-footer"><span>AnPhucRealEstate — sàn NOXH được vận hành bởi An Phuc</span><span>Quy chế đấu giá</span><span>CSKH 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích hành vi (trace: docs/05 §3 · docs/08 §4/§10.2 · docs/06 endpoints 54–58)</div><ol><li><span class="num">1</span><span><b>Tabs = state machine</b> <code>auctions.state</code> (DRAFT → PUBLISHED → IN_PROGRESS → AWARDED/FAILED, CANCELLED terminal); count trong nhãn tab lấy từ metadata API. Tab sync URL <code>?state=</code> — shareable, reload giữ nguyên. <span class="ref">docs/07 §2.9</span> <span class="ref">docs/08 §10.2</span></span></li><li><span class="num">2</span><span><b>DataTable server-side</b> (pattern SC-40..49): <code>GET /admin/auctions?state=</code> + page/limit; đổi tab/sort/page đều refetch, không lọc client. Đang fetch → skeleton 8 dòng (mục 3). <span class="ref">docs/05 §3</span> <span class="ref">endpoint 54</span></span></li><li><span class="num">3</span><span><b>Badge màu theo enum</b>: DRAFT muted · PUBLISHED info · IN_PROGRESS <code>live</code> (nhấp nháy đỏ) · AWARDED ok · FAILED warn · CANCELLED muted. IN_PROGRESS luôn được sort lên đầu trong tab &quot;Tất cả&quot; để Ops không bao giờ bỏ sót phiên đang chạy. <span class="ref">docs/07 §3</span></span></li><li><span class="num">4</span><span><b>Click dòng</b>: IN_PROGRESS → SC-46 monitor; DRAFT → SC-45 (form sửa); PUBLISHED → SC-45 chế độ xem — <b>khóa sửa khi đã có registration ACTIVE</b> (409 <code>AUCTION_LOCKED</code>, cọc đã thu theo cấu hình cũ); AWARDED/FAILED/CANCELLED → SC-46 read-only (feed đã khóa + kết quả). <span class="ref">UC-11 AF-1</span> <span class="ref">BR-AU-09</span></span></li><li><span class="num">5</span><span><b>&quot;Tạo phiên&quot; → SC-45</b> (<code>/admin/dau-gia/create</code>). Chỉ ADMIN tạo/vận hành phiên — v1 seller không tự mở. <span class="ref">BR-AU-01</span> <span class="ref">FR-AU-01</span></span></li><li><span class="num">6</span><span><b>Hủy chỉ khả thi khi DRAFT/PUBLISHED</b> — nút Hủy KHÔNG render ở các state khác (IN_PROGRESS server trả 409 <code>AUCTION_CANNOT_CANCEL</code>). Click → modal mục 2, <b>lý do bắt buộc</b>. <span class="ref">BR-AU-19</span> <span class="ref">FR-AU-10</span> <span class="ref">endpoint 58</span></span></li><li><span class="num">7</span><span><b>Công bố (publish)</b>: server check BR-AU-03 (notice ≥ 7 ngày trước start) — thiếu → 422 <code>NOTICE_TOO_SHORT</code>, toast đỏ đúng message server; đạt → tin LISTED→RESERVED, phiên hiện public (SC-05), mở đăng ký. Toast + audit <code>AUCTION_PUBLISH</code>. <span class="ref">FR-AU-02</span> <span class="ref">endpoint 57</span></span></li><li><span class="num">8</span><span><b>1 tin = 1 phiên đang sống</b> (partial unique state NOT IN FAILED/CANCELLED): tạo phiên cho tin đã có DRAFT/PUBLISHED/IN_PROGRESS → 409, form SC-45 loại tin đó khỏi dropdown ngay từ đầu. <span class="ref">BR-AU-02</span></span></li><li><span class="num">9</span><span><b>Xuất CSV theo filter hiện hành</b> (tab + page query), giới hạn 50k dòng; toast info khi file sẵn sàng. <span class="ref">FR-STAT-02</span> <span class="ref">endpoint 62</span></span></li><li><span class="num">10</span><span><b>Mọi mutation (publish/cancel) → toast + audit log</b> ghi actor, action, entity, diff (kèm reason), ip, traceId — xem lại tại SC-49. Không có ngoại lệ. <span class="ref">BR-ADM-01</span> <span class="ref">FR-ADM-04</span></span></li></ol></div><h2 id="_2-modal-huy-phien-—-ly-do-bat-buoc-neu-hau-qua-bang-so-that" tabindex="-1">2. Modal &quot;Hủy phiên&quot; — lý do bắt buộc, nêu hậu quả bằng số thật <a class="header-anchor" href="#_2-modal-huy-phien-—-ly-do-bat-buoc-neu-hau-qua-bang-so-that" aria-label="Permalink to &quot;2. Modal &quot;Hủy phiên&quot; — lý do bắt buộc, nêu hậu quả bằng số thật&quot;">​</a></h2><div class="wf"><div class="wf-modal-overlay"><div class="wf-modal"><div class="head">Hủy phiên DGA-2026-0003? <span class="wf-callout danger">11</span></div><div class="wf-lines" style="margin:10px 0;"><div class="wf-row between"><span class="wf-text">Căn / Dự án</span><span class="wf-strong">CT1-B07.03 · NOXH HP-380</span></div><div class="wf-row between"><span class="wf-text">Trạng thái hiện tại</span><span class="wf-badge info">PUBLISHED</span></div><div class="wf-row between"><span class="wf-text">Đăng ký ACTIVE</span><span class="wf-strong">3 người · tổng cọc 217.500.000 ₫</span></div><div class="wf-row between"><span class="wf-text">Giờ mở phiên</span><span>12/10/2026 09:00 (GMT+7)</span></div></div><div class="wf-note" style="background:var(--wf-danger-soft);border-color:var(--wf-danger);color:var(--wf-danger);"> Hậu quả: <b>hoàn 100% cọc cho 3 người trong 3 ngày làm việc</b> · tin CT1-B07.03 về <b>LISTED</b> · gửi thông báo tới toàn bộ người đăng ký. <b>Không thể hoàn tác</b> — muốn đấu giá lại phải tạo phiên mới. <span class="wf-callout danger">12</span></div><span class="wf-small wf-strong">Lý do hủy (bắt buộc, 5–500 ký tự) <span class="wf-callout">13</span></span><div class="wf-input filled" style="min-height:64px;align-items:flex-start;">Chủ nhà khiếu nại thông tin sổ đang chờ pháp chế xác minh — tạm hủy để bảo vệ người mua<span class="caret">✎</span></div><div class="wf-row between" style="margin-top:4px;"><span class="wf-small">68/500 ký tự</span><span class="wf-small wf-muted">Ghi vào audit AUCTION_CANCEL — không sửa/xóa được</span></div><div class="wf-row" style="margin-top:12px;"><span class="wf-btn" style="flex:1;">Quay lại</span><span class="wf-btn danger" style="flex:1;">XÁC NHẬN HỦY PHIÊN</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">11</span><span>Modal không tắt được bằng click nền/ESC ngoài nút &quot;Quay lại&quot; (hành động tiền thật). Đang gửi → nút danger loading disabled, chống double-submit. <span class="ref">docs/05 §1.3</span></span></li><li><span class="num">12</span><span>Nêu <b>hậu quả bằng số thật</b> (bao nhiêu người, bao nhiêu tiền cọc, tin về đâu) — theo đúng BR-AU-19: refund 100% cọc ACTIVE trong 3 ngày làm việc + listing → LISTED + NTF toàn bộ registrants (NTF-05). <span class="ref">BR-AU-19</span> <span class="ref">FR-AU-10</span></span></li><li><span class="num">13</span><span><b>Reason bắt buộc</b> — trống hoặc dưới 5 ký tự → disable nút xác nhận + field error &quot;Lý do tối thiểu 5 ký tự&quot;. Thành công → toast ok: <b>&quot;Đã hủy phiên DGA-2026-0003 — hoàn cọc 3 ngày làm việc, tin về LISTED, đã thông báo 3 người đăng ký&quot;</b> + audit. Race (admin khác vừa đổi state) → 409, toast đỏ message server, refresh bảng. <span class="ref">endpoint 58</span> <span class="ref">BR-ADM-01</span></span></li></ol></div><h2 id="_3-trang-thai-rong-loading-loi-quy-tac-4-state" tabindex="-1">3. Trạng thái rỗng / loading / lỗi (quy tắc 4-state) <a class="header-anchor" href="#_3-trang-thai-rong-loading-loi-quy-tac-4-state" aria-label="Permalink to &quot;3. Trạng thái rỗng / loading / lỗi (quy tắc 4-state)&quot;">​</a></h2><div class="wf"><div class="wf-grid cols-3"><div class="wf-col"><span class="wf-state-label">LOADING — SKELETON</span><div class="wf-card"><div class="pad wf-col"><div class="wf-skeleton" style="height:34px;"></div><div class="wf-skeleton" style="height:26px;"></div><div class="wf-skeleton" style="height:26px;"></div><div class="wf-skeleton" style="height:26px;"></div><div class="wf-skeleton" style="height:26px;"></div><span class="wf-small">Skeleton tabs + 8 dòng bảng; giữ nguyên khung để không nhảy layout.</span></div></div></div><div class="wf-col"><span class="wf-state-label">EMPTY — TAB DRAFT TRỐNG</span><div class="wf-empty"><b>Chưa có phiên nháp nào</b><br><span class="wf-small">Tạo phiên từ một tin đang LISTED — hệ thống tự kiểm tra điều kiện công bố (≥ 7 ngày).</span><div style="margin-top:12px;"><span class="wf-btn primary">+ Tạo phiên đầu tiên → SC-45</span></div><span class="wf-small" style="display:block;margin-top:8px;">Tab khác rỗng (vd CANCELLED): cùng khung, bỏ CTA, chỉ hiện &quot;Không có phiên nào ở trạng thái này&quot;.</span></div></div><div class="wf-col"><span class="wf-state-label">ERROR — KHÔNG LOAD ĐƯỢC</span><div class="wf-error-box"><b>Không tải được danh sách phiên</b><br><span class="wf-small">Kiểm tra kết nối và thử lại. Nếu lỗi kéo dài, báo kỹ thuật kèm mã truy vết:</span><br><span class="wf-trace">traceId: 4f2a9c1e-77b0-4d3a</span><div style="margin-top:10px;"><span class="wf-btn">Thử lại</span></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">14</span><span><b>4 trạng thái bắt buộc</b> cho mọi màn dữ liệu admin: Loading (skeleton) → Empty (CTA nếu là điểm khởi tạo) → Error (message + traceId rút gọn + Thử lại) → Data (mục 1). <span class="ref">docs/05 §1.4</span></span></li><li><span class="num">15</span><span>Empty của tab DRAFT là <b>cơ hội hành động</b> (CTA tạo phiên) — các tab còn lại rỗng chỉ là thông tin, không CTA để tránh nhiễu. <span class="ref">docs/05 §3</span></span></li></ol></div><h2 id="_4-checklist-designer-khi-dung-figma-cho-sc-44" tabindex="-1">4. Checklist designer khi dựng Figma cho SC-44 <a class="header-anchor" href="#_4-checklist-designer-khi-dung-figma-cho-sc-44" aria-label="Permalink to &quot;4. Checklist designer khi dựng Figma cho SC-44&quot;">​</a></h2><ul><li>[ ] Đủ 7 tabs trạng thái + count; tab IN_PROGRESS có badge live nhấp nháy (như SC-06)</li><li>[ ] Bảng: đủ 6 cột + cột hành động thay đổi theo state (Monitor / Sửa+Công bố+Hủy / Xem read-only) — vẽ 1 frame ma trận &quot;state → hành động khả dụng&quot;</li><li>[ ] Nút Hủy KHÔNG xuất hiện ở IN_PROGRESS/AWARDED/FAILED/CANCELLED (không chỉ disable — ẩn hẳn, tooltip giải thích khi hover vùng trống là optional)</li><li>[ ] Modal hủy: số thật (người đăng ký, tổng cọc), reason textarea + counter, nút danger, loading state</li><li>[ ] Toast: ok (hủy thành công + hệ quả), danger (409 AUCTION_CANNOT_CANCEL / 422 NOTICE_TOO_SHORT — copy từ server, docs/06 §5)</li><li>[ ] 4-state: skeleton / empty (2 biến thể: có CTA, không CTA) / error+traceId / data</li><li>[ ] Responsive note: admin desktop-priority; ≤768px bảng cuộn ngang, rail thu thành icon-bar (không cần frame mobile riêng)</li><li>[ ] Không emoji icon trong UI production (badge live dùng chấm đỏ CSS, không dùng 🔴)</li><li>[ ] Copy tiền <code>1.800.000.000 ₫</code>, ngày <code>dd/MM/yyyy HH:mm</code> + chú GMT+7; giờ hiển thị Asia/Ho_Chi_Minh</li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ cần PM duyệt trên docs/08 trước.</p></div>',15)])])}const b=a(i,[["render",c]]);export{g as __pageData,b as default};
